self.KB_CONTENT["card:751943"]={"id":"card:751943","ty":"card","sourceId":"751943","title":"『分攤比率資料建立作業』中的『立沖帳目(一) (MP008)』為何？","ver":"iGP","topic":"立沖帳目","keywords":["立沖帳目","科目","編號","比率"],"y":"other","answer":"* 須先輸入科目編號才可輸立沖帳目(一)，否則會顯示科目編號欄位不可空白。* [F2]立沖帳目(一)資料查詢。* 立沖帳目(一)管制方式","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
