self.KB_CONTENT["card:792638"]={"id":"card:792638","ty":"card","sourceId":"792638","title":"『出貨通知單建立作業』中的『材積單位 (TA083)』為何？","ver":"GP4以上","topic":"單位","keywords":["單位","出貨"],"y":"other","answer":"* 材積計算單位分為1.英制(CUFT)及2.公制(CBM)兩種。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
