self.KB_CONTENT["card:782983"]={"id":"card:782983","ty":"card","sourceId":"782983","title":"『BOM用量資料建立』中的『材料型態 (MD017)』為何？","ver":"GP4以上","topic":"領料單","keywords":["領料單","品號","製令","客戶"],"y":"other","answer":"* 可選擇 1.直接材料、2.間接材料、3.廠商供料、4.不發料及5.客戶供料。* 若設定為「3.廠商供料」及「4.不發料」，則於輸入領料單時不會帶出。* 當設定值為直接材料、間接材料、客戶供料時，製令展料將會直接帶出品號。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
