self.KB_CONTENT["card:783104"]={"id":"card:783104","ty":"card","sourceId":"783104","title":"『外匯交割底稿產生作業』中的『選擇交易別』為何？","ver":"GP4以上","topic":"分錄","keywords":["分錄","底稿","交易"],"y":"other","answer":"* 可選擇交易別為1.買、2.賣及3.全部的交割資料產生分錄底稿。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
